/* ==========================================================================
 * chart.umd.min.js -- VENDORED SHIM, NOT THE REAL LIBRARY
 * ==========================================================================
 *
 * A small canvas charting engine that implements the subset of the Chart.js
 * v4 API this dashboard actually uses. It exists so the pages render
 * correctly **offline**, with no CDN and no build step.
 *
 * TO USE THE REAL LIBRARY
 * -----------------------
 *   1. Download https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js
 *   2. Overwrite this file with it. Same filename, same <script> tag.
 *   3. Change nothing else. Every chart config in the templates is written as
 *      a valid Chart.js v4 config -- same option paths, same callback
 *      signatures -- so the real library renders the same charts with nicer
 *      animation and far more polish.
 *
 * IMPLEMENTED
 * -----------
 *   type: "bar" | "line", and mixed charts via a per-dataset `type`
 *   data:    { labels: [...], datasets: [{ label, data, type, backgroundColor,
 *              borderColor, borderWidth, borderDash, borderRadius, pointRadius,
 *              tension (straight lines only), order, barPercentage }] }
 *   options: responsive, maintainAspectRatio,
 *            scales.y  { min, max, beginAtZero, suggestedMax, stepSize,
 *                        ticks.callback(value), grid.color, grid.display }
 *            scales.x  { grid.display, ticks.color }
 *            plugins.legend  { display }
 *            plugins.tooltip { enabled, callbacks.title(items),
 *                              callbacks.label(item) }
 *   instance: .update(), .destroy(), .data, .options, .canvas
 *   statics:  Chart.defaults.color / .font.family / .borderColor
 *
 *   `null` in a dataset is a genuine gap: the line breaks and no bar is
 *   drawn. That matters here -- an acceptance rate of null means "nothing was
 *   offered in this hour", which is not zero.
 *
 * NOT IMPLEMENTED
 * ---------------
 *   pie/doughnut/radar/scatter/bubble, stacked scales, second y axis (the
 *   project forbids dual-axis charts anyway), animations, area fill,
 *   logarithmic/time scales, plugins, curve interpolation, decimation.
 * ========================================================================== */

(function (global) {
  "use strict";

  var DPR = function () {
    return global.devicePixelRatio || 1;
  };

  var defaults = {
    color: "#898781",
    borderColor: "rgba(128,128,128,0.25)",
    font: { family: 'system-ui, -apple-system, "Segoe UI", sans-serif', size: 11 }
  };

  /* ------------------------------------------------------------------ maths */

  function niceStep(range, targetCount) {
    if (!isFinite(range) || range <= 0) return 1;
    var raw = range / Math.max(targetCount, 1);
    var mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10));
    var norm = raw / mag;
    var mult = norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 2.5 ? 2.5 : norm <= 5 ? 5 : 10;
    return mult * mag;
  }

  function cleanNumber(value, step) {
    var decimals = step < 1 ? Math.min(6, Math.ceil(-Math.log(step) / Math.LN10) + 1) : 0;
    return parseFloat(value.toFixed(decimals));
  }

  function buildTicks(min, max, step) {
    var ticks = [];
    var guard = 0;
    for (var value = min; value <= max + step / 1000 && guard < 200; value += step, guard++) {
      ticks.push(cleanNumber(value, step));
    }
    if (ticks.length && ticks[ticks.length - 1] < max) ticks.push(cleanNumber(max, step));
    return ticks;
  }

  function numericValues(datasets) {
    var out = [];
    for (var i = 0; i < datasets.length; i++) {
      var data = datasets[i].data || [];
      for (var j = 0; j < data.length; j++) {
        var value = data[j];
        if (value !== null && value !== undefined && isFinite(value)) out.push(+value);
      }
    }
    return out;
  }

  /* ------------------------------------------------------------ canvas bits */

  function roundedTopRect(ctx, x, y, width, height, radius) {
    var r = Math.max(0, Math.min(radius, width / 2, Math.abs(height)));
    var down = height >= 0;
    var top = down ? y : y + height;
    var h = Math.abs(height);
    ctx.beginPath();
    if (down) {
      ctx.moveTo(x, top + h);
      ctx.lineTo(x, top + r);
      ctx.quadraticCurveTo(x, top, x + r, top);
      ctx.lineTo(x + width - r, top);
      ctx.quadraticCurveTo(x + width, top, x + width, top + r);
      ctx.lineTo(x + width, top + h);
    } else {
      ctx.moveTo(x, top);
      ctx.lineTo(x, top + h - r);
      ctx.quadraticCurveTo(x, top + h, x + r, top + h);
      ctx.lineTo(x + width - r, top + h);
      ctx.quadraticCurveTo(x + width, top + h, x + width, top + h - r);
      ctx.lineTo(x + width, top);
    }
    ctx.closePath();
  }

  function textWidth(ctx, text) {
    return ctx.measureText(String(text)).width;
  }

  /* ----------------------------------------------------------------- Chart */

  function Chart(item, config) {
    if (!(this instanceof Chart)) return new Chart(item, config);
    this.canvas = item && item.getContext ? item : item && item.canvas ? item.canvas : null;
    if (!this.canvas) throw new Error("Chart: first argument must be a <canvas>");
    this.ctx = this.canvas.getContext("2d");
    this.config = config || {};
    this.data = this.config.data || { labels: [], datasets: [] };
    this.options = this.config.options || {};
    this.type = this.config.type || "bar";
    this._hover = -1;
    this._destroyed = false;
    this._frame = null;

    this._buildTooltip();
    this._bind();
    this.update();

    Chart.instances.push(this);
  }

  Chart.instances = [];
  Chart.defaults = defaults;
  Chart.version = "shim-4.x-compatible";

  Chart.getChart = function (canvas) {
    for (var i = 0; i < Chart.instances.length; i++) {
      if (Chart.instances[i].canvas === canvas) return Chart.instances[i];
    }
    return undefined;
  };

  Chart.prototype._buildTooltip = function () {
    var parent = this.canvas.parentNode;
    if (!parent) return;
    var node = document.createElement("div");
    node.className = "tbk-tooltip";
    node.setAttribute("role", "status");
    parent.appendChild(node);
    this._tooltip = node;
  };

  Chart.prototype._bind = function () {
    var self = this;

    this._onMove = function (event) {
      var rect = self.canvas.getBoundingClientRect();
      self._pointer = { x: event.clientX - rect.left, y: event.clientY - rect.top };
      var index = self._indexAt(self._pointer.x);
      if (index !== self._hover) {
        self._hover = index;
        self.render();
      }
      self._positionTooltip();
    };
    this._onLeave = function () {
      self._pointer = null;
      if (self._hover !== -1) {
        self._hover = -1;
        self.render();
      }
      self._hideTooltip();
    };

    this.canvas.addEventListener("mousemove", this._onMove);
    this.canvas.addEventListener("mouseleave", this._onLeave);

    if (global.ResizeObserver && this.canvas.parentNode) {
      this._observer = new global.ResizeObserver(function () {
        self.resize();
      });
      this._observer.observe(this.canvas.parentNode);
    } else {
      this._onResize = function () {
        self.resize();
      };
      global.addEventListener("resize", this._onResize);
    }
  };

  Chart.prototype.resize = function () {
    var self = this;
    if (this._frame) return;
    this._frame = global.requestAnimationFrame(function () {
      self._frame = null;
      if (!self._destroyed) self.render();
    });
  };

  Chart.prototype.update = function () {
    this.data = this.config.data || this.data;
    this.options = this.config.options || this.options;
    this.render();
  };

  Chart.prototype.destroy = function () {
    this._destroyed = true;
    this.canvas.removeEventListener("mousemove", this._onMove);
    this.canvas.removeEventListener("mouseleave", this._onLeave);
    if (this._observer) this._observer.disconnect();
    if (this._onResize) global.removeEventListener("resize", this._onResize);
    if (this._tooltip && this._tooltip.parentNode) this._tooltip.parentNode.removeChild(this._tooltip);
    var at = Chart.instances.indexOf(this);
    if (at > -1) Chart.instances.splice(at, 1);
    var ctx = this.ctx;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
  };

  /* ------------------------------------------------------------- geometry */

  Chart.prototype._option = function (path, fallback) {
    var parts = path.split(".");
    var node = this.options;
    for (var i = 0; i < parts.length; i++) {
      if (node === null || node === undefined) return fallback;
      node = node[parts[i]];
    }
    return node === undefined ? fallback : node;
  };

  Chart.prototype._layout = function () {
    var ctx = this.ctx;
    var css = this._css;
    var labels = this.data.labels || [];
    var datasets = this.data.datasets || [];

    /* ---- y scale ---- */
    var values = numericValues(datasets);
    var beginAtZero = this._option("scales.y.beginAtZero", true);
    var explicitMin = this._option("scales.y.min", undefined);
    var explicitMax = this._option("scales.y.max", undefined);
    var suggestedMax = this._option("scales.y.suggestedMax", undefined);

    var dataMin = values.length ? Math.min.apply(null, values) : 0;
    var dataMax = values.length ? Math.max.apply(null, values) : 1;
    if (beginAtZero) dataMin = Math.min(0, dataMin);
    if (suggestedMax !== undefined) dataMax = Math.max(dataMax, suggestedMax);
    if (dataMax === dataMin) dataMax = dataMin + 1;

    var min = explicitMin !== undefined ? explicitMin : dataMin;
    var max = explicitMax !== undefined ? explicitMax : dataMax;

    var step = this._option("scales.y.stepSize", undefined);
    if (step === undefined) step = niceStep(max - min, 4);
    if (explicitMin === undefined) min = Math.floor(min / step) * step;
    if (explicitMax === undefined) max = Math.ceil(max / step) * step;
    if (max === min) max = min + step;

    var ticks = buildTicks(min, max, step);
    var callback = this._option("scales.y.ticks.callback", null);
    var tickLabels = ticks.map(function (value, index) {
      return callback ? String(callback.call(null, value, index, ticks)) : String(value);
    });

    /* ---- plot area ---- */
    ctx.font = defaults.font.size + "px " + defaults.font.family;
    var widest = 0;
    for (var i = 0; i < tickLabels.length; i++) {
      widest = Math.max(widest, textWidth(ctx, tickLabels[i]));
    }

    var legendShown = this._option("plugins.legend.display", false) !== false;
    var legendHeight = legendShown ? 20 : 0;

    var padLeft = widest + 12;
    var padRight = 10;
    var padTop = 10 + legendHeight;
    var padBottom = labels.length ? 22 : 10;

    return {
      min: min,
      max: max,
      ticks: ticks,
      tickLabels: tickLabels,
      left: padLeft,
      right: css.width - padRight,
      top: padTop,
      bottom: css.height - padBottom,
      legendHeight: legendHeight,
      count: labels.length
    };
  };

  Chart.prototype._yFor = function (value, box) {
    var span = box.max - box.min || 1;
    var ratio = (value - box.min) / span;
    return box.bottom - ratio * (box.bottom - box.top);
  };

  Chart.prototype._categoryWidth = function (box) {
    return box.count ? (box.right - box.left) / box.count : box.right - box.left;
  };

  Chart.prototype._centerFor = function (index, box) {
    var width = this._categoryWidth(box);
    return box.left + width * (index + 0.5);
  };

  Chart.prototype._indexAt = function (x) {
    var box = this._box;
    if (!box || !box.count) return -1;
    if (x < box.left - 4 || x > box.right + 4) return -1;
    var width = this._categoryWidth(box);
    var index = Math.floor((x - box.left) / width);
    return Math.max(0, Math.min(box.count - 1, index));
  };

  /* --------------------------------------------------------------- render */

  Chart.prototype.render = function () {
    if (this._destroyed) return;
    var canvas = this.canvas;
    var parent = canvas.parentNode;
    var cssWidth = canvas.clientWidth || (parent ? parent.clientWidth : 0) || 320;
    var cssHeight = canvas.clientHeight || (parent ? parent.clientHeight : 0) || 180;
    this._css = { width: cssWidth, height: cssHeight };

    var dpr = DPR();
    canvas.width = Math.max(1, Math.round(cssWidth * dpr));
    canvas.height = Math.max(1, Math.round(cssHeight * dpr));

    var ctx = this.ctx;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssWidth, cssHeight);
    ctx.font = defaults.font.size + "px " + defaults.font.family;
    ctx.textBaseline = "middle";

    var datasets = this.data.datasets || [];
    var labels = this.data.labels || [];
    if (!labels.length || !datasets.length || !numericValues(datasets).length) {
      ctx.fillStyle = defaults.color;
      ctx.textAlign = "center";
      ctx.fillText("No data for this window", cssWidth / 2, cssHeight / 2);
      this._box = null;
      this._hideTooltip();
      return;
    }

    var box = this._layout();
    this._box = box;

    this._drawGrid(box);
    this._drawBars(box);
    this._drawLines(box);
    this._drawAxes(box);
    if (box.legendHeight) this._drawLegend(box);
    if (this._hover > -1) this._drawHover(box);
    this._renderTooltip(box);
  };

  Chart.prototype._drawGrid = function (box) {
    var ctx = this.ctx;
    if (this._option("scales.y.grid.display", true) === false) return;
    ctx.save();
    ctx.strokeStyle = this._option("scales.y.grid.color", defaults.borderColor);
    ctx.lineWidth = 1;
    for (var i = 0; i < box.ticks.length; i++) {
      var y = Math.round(this._yFor(box.ticks[i], box)) + 0.5;
      ctx.beginPath();
      ctx.moveTo(box.left, y);
      ctx.lineTo(box.right, y);
      ctx.stroke();
    }
    ctx.restore();
  };

  Chart.prototype._drawAxes = function (box) {
    var ctx = this.ctx;
    var labels = this.data.labels || [];
    ctx.save();
    ctx.fillStyle = this._option("scales.y.ticks.color", defaults.color);
    ctx.textAlign = "right";
    for (var i = 0; i < box.ticks.length; i++) {
      ctx.fillText(box.tickLabels[i], box.left - 7, this._yFor(box.ticks[i], box));
    }

    /* x labels, auto-skipped so they never collide */
    ctx.fillStyle = this._option("scales.x.ticks.color", defaults.color);
    ctx.textAlign = "center";
    var widest = 8;
    for (var j = 0; j < labels.length; j++) {
      widest = Math.max(widest, textWidth(ctx, labels[j]));
    }
    var fits = Math.max(1, Math.floor((box.right - box.left) / (widest + 12)));
    var stride = Math.ceil(labels.length / fits);
    var y = box.bottom + 12;
    for (var k = 0; k < labels.length; k += stride) {
      ctx.fillText(String(labels[k]), this._centerFor(k, box), y);
    }
    ctx.restore();
  };

  Chart.prototype._barDatasets = function () {
    var self = this;
    return (this.data.datasets || []).filter(function (dataset) {
      return (dataset.type || self.type) === "bar";
    });
  };

  Chart.prototype._drawBars = function (box) {
    var bars = this._barDatasets();
    if (!bars.length) return;
    var ctx = this.ctx;
    var categoryWidth = this._categoryWidth(box);
    var groupWidth = categoryWidth * (this._option("datasets.bar.barPercentage", 0.78));
    var slot = groupWidth / bars.length;
    var gap = bars.length > 1 ? 2 : 0; /* 2px surface gap between adjacent bars */
    var barWidth = Math.max(1, slot - gap);
    var zero = this._yFor(Math.max(box.min, 0), box);

    for (var d = 0; d < bars.length; d++) {
      var dataset = bars[d];
      ctx.fillStyle = dataset.backgroundColor || defaults.color;
      for (var i = 0; i < (dataset.data || []).length; i++) {
        var value = dataset.data[i];
        if (value === null || value === undefined || !isFinite(value)) continue;
        var center = this._centerFor(i, box);
        var x = center - groupWidth / 2 + d * slot + gap / 2;
        var y = this._yFor(value, box);
        var height = y - zero;
        if (Math.abs(height) < 1 && value !== 0) height = height < 0 ? -1 : 1;
        roundedTopRect(ctx, x, zero, barWidth, height, 4);
        ctx.fill();
        if (dataset.borderWidth && dataset.borderColor) {
          ctx.lineWidth = dataset.borderWidth;
          ctx.strokeStyle = dataset.borderColor;
          ctx.stroke();
        }
      }
    }
  };

  Chart.prototype._drawLines = function (box) {
    var self = this;
    var lines = (this.data.datasets || []).filter(function (dataset) {
      return (dataset.type || self.type) === "line";
    });
    if (!lines.length) return;
    var ctx = this.ctx;

    for (var d = 0; d < lines.length; d++) {
      var dataset = lines[d];
      var data = dataset.data || [];
      ctx.save();
      ctx.strokeStyle = dataset.borderColor || defaults.color;
      ctx.lineWidth = dataset.borderWidth === undefined ? 2 : dataset.borderWidth;
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      if (dataset.borderDash && dataset.borderDash.length) ctx.setLineDash(dataset.borderDash);

      var drawing = false;
      ctx.beginPath();
      for (var i = 0; i < data.length; i++) {
        var value = data[i];
        if (value === null || value === undefined || !isFinite(value)) {
          drawing = false; /* a null is a real gap, not a zero */
          continue;
        }
        var x = this._centerFor(i, box);
        var y = this._yFor(value, box);
        if (!drawing) {
          ctx.moveTo(x, y);
          drawing = true;
        } else {
          ctx.lineTo(x, y);
        }
      }
      ctx.stroke();
      ctx.setLineDash([]);

      var radius = dataset.pointRadius === undefined ? 0 : dataset.pointRadius;
      if (radius > 0) {
        ctx.fillStyle = dataset.borderColor || defaults.color;
        for (var j = 0; j < data.length; j++) {
          var point = data[j];
          if (point === null || point === undefined || !isFinite(point)) continue;
          ctx.beginPath();
          ctx.arc(this._centerFor(j, box), this._yFor(point, box), radius, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.restore();
    }
  };

  Chart.prototype._drawLegend = function (box) {
    var ctx = this.ctx;
    var datasets = this.data.datasets || [];
    ctx.save();
    ctx.textAlign = "left";
    ctx.fillStyle = defaults.color;
    var x = box.left;
    var y = 12;
    for (var i = 0; i < datasets.length; i++) {
      var dataset = datasets[i];
      var color = dataset.backgroundColor || dataset.borderColor || defaults.color;
      ctx.fillStyle = color;
      ctx.fillRect(x, y - 4, 9, 9);
      ctx.fillStyle = defaults.color;
      var label = dataset.label || "Series " + (i + 1);
      ctx.fillText(label, x + 14, y);
      x += 14 + textWidth(ctx, label) + 18;
    }
    ctx.restore();
  };

  Chart.prototype._drawHover = function (box) {
    var ctx = this.ctx;
    var index = this._hover;
    if (index < 0 || index >= box.count) return;
    var x = this._centerFor(index, box);
    ctx.save();
    ctx.strokeStyle = defaults.color;
    ctx.globalAlpha = 0.45;
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(Math.round(x) + 0.5, box.top);
    ctx.lineTo(Math.round(x) + 0.5, box.bottom);
    ctx.stroke();
    ctx.restore();
  };

  /* -------------------------------------------------------------- tooltip */

  Chart.prototype._items = function (index) {
    var self = this;
    var labels = this.data.labels || [];
    var items = [];
    (this.data.datasets || []).forEach(function (dataset, datasetIndex) {
      var value = (dataset.data || [])[index];
      if (value === null || value === undefined) return;
      items.push({
        chart: self,
        label: labels[index],
        dataset: dataset,
        datasetIndex: datasetIndex,
        dataIndex: index,
        raw: value,
        parsed: { x: index, y: value },
        formattedValue: String(value)
      });
    });
    return items;
  };

  Chart.prototype._renderTooltip = function (box) {
    if (!this._tooltip) return;
    if (this._option("plugins.tooltip.enabled", true) === false) return;
    var index = this._hover;
    if (index < 0 || !this._pointer) {
      this._hideTooltip();
      return;
    }
    var items = this._items(index);
    if (!items.length) {
      this._hideTooltip();
      return;
    }

    var titleCb = this._option("plugins.tooltip.callbacks.title", null);
    var labelCb = this._option("plugins.tooltip.callbacks.label", null);
    var title = titleCb ? titleCb.call(null, items) : items[0].label;
    if (Array.isArray(title)) title = title.join(" ");

    var html = '<div class="t-title">' + escapeHtml(title) + "</div>";
    for (var i = 0; i < items.length; i++) {
      var item = items[i];
      var text = labelCb
        ? labelCb.call(null, item)
        : (item.dataset.label ? item.dataset.label + ": " : "") + item.formattedValue;
      if (Array.isArray(text)) text = text.join(" ");
      if (text === null || text === undefined || text === "") continue;
      var color = item.dataset.backgroundColor || item.dataset.borderColor || defaults.color;
      html +=
        '<div class="t-row"><span class="t-swatch" style="background:' +
        escapeHtml(String(color)) +
        '"></span><span>' +
        escapeHtml(String(text)) +
        "</span></div>";
    }
    this._tooltip.innerHTML = html;
    this._tooltip.classList.add("on");
    this._positionTooltip();
  };

  Chart.prototype._positionTooltip = function () {
    if (!this._tooltip || !this._box || this._hover < 0) return;
    var x = this._centerFor(this._hover, this._box);
    var y = Math.max(this._box.top, (this._pointer ? this._pointer.y : this._box.top) - 12);
    var width = this._tooltip.offsetWidth;
    var half = width / 2;
    var canvasWidth = this._css.width;
    var clamped = Math.min(Math.max(x, half + 4), canvasWidth - half - 4);
    this._tooltip.style.left = clamped + "px";
    this._tooltip.style.top = y + "px";
  };

  Chart.prototype._hideTooltip = function () {
    if (this._tooltip) this._tooltip.classList.remove("on");
  };

  function escapeHtml(value) {
    return String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  global.Chart = Chart;
})(window);
